#include <atcoder/modint>
#include SOURCE
#include <algorithm>
#include <cstdint>
#include <cstdio>
#include <limits>
#include <optional>
#include <queue>
#include <random>
#include <stdexcept>
#include <utility>
#include <vector>
struct Ring{std::uint64_t x;Ring(std::int64_t v=0):x(static_cast<std::uint64_t>(v)){}friend Ring operator+(Ring a,Ring b){a.x+=b.x;return a;}friend Ring operator-(Ring a,Ring b){a.x-=b.x;return a;}friend bool operator==(Ring,Ring)=default;};
static std::uint64_t checks=0;
static void ck(bool b){++checks;if(!b)throw std::runtime_error("reference mismatch");}
template<class T>void run(){
 using UF=RollbackWeightedUnionFind<T>;using R=typename UF::MergeResult;
 const int n=24;UF uf(n);std::vector<std::vector<std::pair<int,T>>> graph(n);using Graph=decltype(graph);std::vector<Graph> hist;int snap=0;std::mt19937 rng(91022);
 const auto diff=[&](int s,int t)->std::optional<T>{std::vector<bool>seen(n);std::vector<T>w(n,T(0));std::queue<int>q;q.push(s);seen[s]=true;while(!q.empty()){int v=q.front();q.pop();if(v==t)return w[v];for(const auto&[u,d]:graph[v])if(!seen[u]){seen[u]=true;w[u]=w[v]+d;q.push(u);}}return std::nullopt;};
 for(int it=0;it<2500;++it){int op=static_cast<int>(rng()%9),a=static_cast<int>(rng()%n),b=static_cast<int>(rng()%n);T w(static_cast<int>(rng()%31)-15);
  if(op<4){auto d=diff(a,b);hist.push_back(graph);if(op==0){ck(uf.unite(a,b,w)==!d);}else{const auto expected=!d?R::Merged:(*d==w?R::AlreadyConsistent:R::Contradiction);ck(uf.unite_checked(a,b,w)==expected);}if(!d){graph[a].emplace_back(b,w);graph[b].emplace_back(a,T(0)-w);}}
  else if(op==4&&!hist.empty()){uf.undo();graph=hist.back();hist.pop_back();snap=std::min(snap,static_cast<int>(hist.size()));}
  else if(op==5){uf.snapshot();snap=uf.get_state();}
  else if(op==6){const int state=static_cast<int>(rng()%(hist.size()+1));uf.rollback(state);if(state<static_cast<int>(hist.size()))graph=hist[state];hist.resize(state);snap=std::min(snap,state);}
  else if(op==7){uf.rollback();if(snap<static_cast<int>(hist.size()))graph=hist[snap];hist.resize(snap);}
  else {auto cp=uf;ck(cp.get_state()==uf.get_state());for(int i=0;i<n;++i)ck(cp.get_weight(i)==uf.get_weight(i));}
  ck(uf.get_state()==static_cast<int>(hist.size()));
  for(int k=0;k<12;++k){a=static_cast<int>(rng()%n);b=static_cast<int>(rng()%n);auto d=diff(a,b);ck(uf.same(a,b)==bool(d));ck(uf.try_diff(a,b)==d);if(d)ck(uf.diff(a,b)==*d);ck(uf.consistent(a,b,w)==(!d||*d==w));auto [root,weight]=uf.root_with_weight(a);ck(root==uf.find(a));ck(diff(root,a)==weight);ck(uf.get_weight(a)==weight);}
  if(it%97==0){auto groups=uf.groups();int total=0;ck(static_cast<int>(groups.size())==uf.component_count());for(const auto&g:groups){ck(std::is_sorted(g.begin(),g.end()));for(int x:g){++total;ck(uf.size(x)==static_cast<int>(g.size()));ck(bool(diff(g.front(),x)));}}ck(total==n);}
 }
}
int main(){run<std::int64_t>();run<std::uint64_t>();run<atcoder::modint998244353>();run<Ring>();using UF=RollbackWeightedUnionFind<std::int64_t>;const auto mx=std::numeric_limits<std::int64_t>::max();UF u(6);ck(u.unite(0,1,mx));ck(u.unite(0,2,mx-1));ck(u.diff(1,2)==-1);ck(u.try_diff(1,2)==-1);ck(u.consistent(1,2,-1));u.undo();ck(u.get_weight(2)==0);ck(u.diff(2,2)==0);ck(u.try_diff(2,2)==0);ck(u.unite(2,3,-mx));ck(u.get_weight(3)==-mx);u.rollback(0);ck(u.get_weight(3)==0);ck(u.try_diff(3,3)==0);std::printf("PASS checks=%ju\n",static_cast<std::uintmax_t>(checks));}

