from pathlib import Path
import subprocess,json,hashlib,statistics,time,fcntl,sys
p=Path(__file__).parent;b=p/'baseline';stage=sys.argv[1];o=p/stage;o.mkdir(exist_ok=True);reps=7 if stage=='final_performance'else 3;sha=lambda x:hashlib.sha256(x).hexdigest()
baseline=b/'DataStructure/rollback-union-findw.cpp';variants={'baseline':baseline,'control':baseline,'final':p/'final.hpp'}if stage=='final_performance'else{'baseline':baseline,'control':baseline,'bothgroups':p/'opt/bothgroups.hpp','bothlazy':p/'opt/bothlazy.hpp'}
original=(b/'Verify/current/submissions/rollback_weighted_union_find.cpp').read_bytes();assert original.count(baseline.read_bytes())==1
modes={'gcc':['g++'],'clang':['clang++','--gcc-install-dir=/opt/atcoder/gcc/lib/gcc/x86_64-pc-linux-gnu/15.3.0']};builds=[]
for name,src in variants.items():(o/(name+'.hpp')).write_bytes(src.read_bytes());(o/(name+'.cpp')).write_bytes(original.replace(baseline.read_bytes(),src.read_bytes(),1))
for mode,cc in modes.items():
 for name,src in variants.items():
  cmd=['taskset','-c','6',*cc,'-std=c++23','-O2',str(o/(name+'.cpp')),'-o',str(o/(mode+'_'+name))];result=subprocess.run(cmd,capture_output=True,check=True);assert not result.stderr;builds.append({'mode':mode,'variant':name,'command':cmd,'header_sha256':sha((o/(name+'.hpp')).read_bytes()),'translation_unit_sha256':sha((o/(name+'.cpp')).read_bytes()),'binary_sha256':sha((o/(mode+'_'+name)).read_bytes())})
cases=[p/'official'/c for c in ['random_00.in','max_random_00.in','max_random_01.in','path_00.in','path_01.in','path_02.in','path_03.in']]+[p/'custom'/c for c in ['balanced.in','star_same_component.in','tiny_random.in','disconnected_pairs.in']]
refs={c.name:(p/'reference_outputs'/(c.name+'.out')).read_bytes().split()for c in cases};raw={m:{v:{c.name:[]for c in cases}for v in variants}for m in modes};outputs={};cache=set()
with open('/tmp/atcoder_full_performance_20261018/benchmark.lock','a')as lock:
 print('waiting lock',flush=True);fcntl.flock(lock,fcntl.LOCK_EX)
 for rep in range(reps):
  for m in modes:
   for c in cases:
    names=list(variants);names=names[rep%len(names):]+names[:rep%len(names)]
    for v in names:
     start=time.perf_counter_ns()
     with c.open('rb')as inp:out=subprocess.check_output(['taskset','-c','14',str(o/(m+'_'+v))],stdin=inp)
     ms=(time.perf_counter_ns()-start)/1e6;digest=sha(out);key=(c.name,digest)
     if key not in cache:assert out.split()==refs[c.name];cache.add(key)
     raw[m][v][c.name].append(ms);outputs.setdefault(m,{}).setdefault(v,{})[c.name]=digest
  print('round',rep,'done',flush=True)
med={m:{v:{c:statistics.median(xs)for c,xs in cs.items()}for v,cs in vs.items()}for m,vs in raw.items()};ratios={m:{v:{c:t/vs['baseline'][c]for c,t in cs.items()}for v,cs in vs.items()}for m,vs in med.items()}
(o/'results.json').write_text(json.dumps({'raw_ms':raw,'medians_ms':med,'ratios':ratios,'builds':builds,'outputs':outputs,'inputs':{c.name:{'sha256':sha(c.read_bytes()),'reference_output_sha256':sha((p/'reference_outputs'/(c.name+'.out')).read_bytes())}for c in cases},'repetitions':reps,'cpu_affinity':14,'parent_cpu_affinity':6,'stdin':'pre-generated regular input file','note':'baseline提出コード内の本体だけを置換しmain/共通fastIO/ACL展開/flags/checksを固定。入力準備と独立参照照合は計時外。実行と結果出力・保存領域破棄を含む。'},ensure_ascii=False,indent=2)+'\n')
